// Brings the brand into the UI by script, never by hand (05 section 1.4 and "one source of truth").
//
// Reads (never writes) brand/: generated/tokens.css, tokens.json and the approved logo and favicon files.
// Writes, under frontend/ (each generated file says so in its first line; never edit them):
//   src/styles/generated/tokens.css            brand/generated/tokens.css, byte for byte
//   src/styles/generated/theme.css             the Tailwind v4 @theme, from the light :root block of that file
//   src/styles/generated/shelfsync-tokens.css  the ShelfSync token layer (P3.4 section 4): app-bar tokens, the
//                                              .tone-dark scope, fixed type sizes, code at 14 px, the tint amounts
//   src/assets/brand/logo-primary-dark.svg     the app-bar lockup (the bar is ink in both themes)
//   public/favicon.svg, public/favicon.ico     served from the site root
//
// Why a copy and not an import from ../brand: Vite, Tailwind and Biome then only read files inside frontend/, and
// `npm run build` runs this script with --check first, so a copy that is out of step with brand/ fails the build
// instead of shipping. A token change is taken in a reviewed commit: `npm run tokens`, then commit the result.
//
// Usage (from frontend/):  node scripts/sync-tokens.mjs           write the files
//                          node scripts/sync-tokens.mjs --check   exit 1 if any file differs from what it would write
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const frontend = join(here, "..");
const brand = join(frontend, "..", "brand");

const tokensCss = readFileSync(join(brand, "generated", "tokens.css"));
const tokensJson = JSON.parse(readFileSync(join(brand, "tokens.json"), "utf8"));

const rem = (px) => `${px / 16}rem`;
const resolve = (name) => {
  const hex = name.startsWith("#") ? name : tokensJson.palette[name];
  if (!hex) throw new Error(`tokens.json: no palette entry "${name}"`);
  return hex.toLowerCase();
};

/** Every `--name: value;` declaration of the first `:root { … }` block (the light theme and the static tokens). */
function lightRootDeclarations(css) {
  const start = css.indexOf(":root {");
  const end = css.indexOf("\n}", start);
  if (start < 0 || end < 0) throw new Error("tokens.css: no :root block");
  return [...css.slice(start, end).matchAll(/^\s*(--[\w-]+):\s*([^;]+);/gm)].map(([, name, value]) => [name, value]);
}

function themeCss() {
  const declarations = lightRootDeclarations(tokensCss.toString("utf8"));
  const space1 = declarations.find(([name]) => name === "--space-1");
  if (!space1) throw new Error("tokens.css: no --space-1");
  const lines = [
    "/* Generated by frontend/scripts/sync-tokens.mjs from brand/generated/tokens.css. Do not edit. */",
    "/* The Tailwind v4 theme: Tailwind's own defaults are cleared, so every utility comes from the brand tokens.",
    "   Tailwind emits these in its theme layer; the unlayered tokens.css (imported after) holds the same light values",
    "   and the dark ones, so the dark theme switches every utility too. */",
    "@theme {",
    "  --*: initial;",
    `  --spacing: ${space1[1]};`,
    ...declarations.map(([name, value]) => `  ${name}: ${value};`),
    "}",
    "",
  ];
  return lines.join("\n");
}

// The ShelfSync token layer. Each value is a brand token, a size read from tokens.json, or a mix amount recorded in
// docs/runs/p3.4-mockups.md section 4 ("color-mix() tints"). Components use these names; none types a value.
const APP_BAR = { light: "ink-900", dark: "ink-750", fg: "mist", muted: "ink-300" }; // 05 section 2.2
const TINTS = [
  // [token, amount, what it is used for] (P3.4 section 4)
  ["--tint-danger-hover", "8%", "danger into surface: hover fill of outline danger buttons"],
  ["--tint-alert", "7%", "tone into surface: inline alert fill"],
  ["--tint-pill-fill", "10%", "tone into surface: BandPill and StatePill fill"],
  ["--tint-pill-border", "35%", "tone into surface: BandPill and StatePill border (decorative)"],
  ["--tint-step-failed", "10%", "danger into surface: failed StepChip fill"],
  ["--tint-lower", "6%", "danger into surface: VersionCompare lower side"],
  ["--tint-selected-card", "45%", "selection into surface: selected CandidateCard and radio card"],
  ["--tint-reason-minus", "40%", "danger into surface: border of minus reason chips (decorative)"],
  ["--tint-danger-solid-hover", "85%", "danger into text: hover of solid danger buttons"],
  ["--tint-banner", "9%", "danger into surface: ERR-04 low-disk banner"],
  ["--tint-update-card", "50%", "selection into surface: update-ready card"],
  ["--tint-backdrop", "55%", "ink-950 into transparent: modal backdrop"],
];

function layerCss() {
  const dark = Object.entries(tokensJson.semantic).map(([name, value]) => `  --color-${name}: ${resolve(value.dark)};`);
  const t = tokensJson.text;
  return [
    "/* Generated by frontend/scripts/sync-tokens.mjs from brand/tokens.json. Do not edit. */",
    "/* The ShelfSync token layer (05 sections 2.2 and 3; docs/runs/p3.4-mockups.md section 4). */",
    ":root {",
    "  /* 05 section 2.2: the app bar is ink in both themes; its contents use the .tone-dark scope below */",
    `  --color-appbar-bg: var(--color-${APP_BAR.light});`,
    `  --color-appbar-fg: var(--color-${APP_BAR.fg});`,
    `  --color-appbar-muted: var(--color-${APP_BAR.muted});`,
    "  /* 05 section 3: fixed sizes in the app (the site's fluid clamps start at these: tokens.json min values) */",
    `  --app-text-title: ${rem(t["display-2"].min)};`,
    `  --app-text-title--line-height: ${t["display-2"].lineHeight};`,
    `  --app-text-title--font-weight: ${t["display-2"].weight};`,
    `  --app-text-kpi: ${rem(t.h2.min)};`,
    "  /* 05 section 3: code (file names, slugs, hashes) at 14 px, the app's text-sm (tokens.json code is the site's 15 px) */",
    `  --app-text-code: ${rem(t.sm.size)};`,
    "  --app-text-code--line-height: 1.5;",
    "  /* shell geometry, from the spacing scale */",
    "  --app-bar-height: calc(var(--space-12) + var(--space-2));",
    "  --app-cut: var(--space-3); /* the diagonal cut on the active nav item (05 section 4) */",
    "  /* color-mix() amounts (P3.4 section 4): components mix a tone token into a surface token by these */",
    ...TINTS.map(([name, amount, use]) => `  ${name}: ${amount}; /* ${use} */`),
    "}",
    "",
    "@media (prefers-color-scheme: dark) {",
    '  :root:not([data-theme="light"]) {',
    `    --color-appbar-bg: var(--color-${APP_BAR.dark});`,
    "  }",
    "}",
    "",
    ':root[data-theme="dark"] {',
    `  --color-appbar-bg: var(--color-${APP_BAR.dark});`,
    "}",
    "",
    "/* The dark semantic values, scoped: for the app bar, which is ink in both themes */",
    ".tone-dark {",
    "  color-scheme: dark;",
    ...dark,
    `  --elevation-1: ${tokensJson.shadow["1"].dark};`,
    `  --elevation-2: ${tokensJson.shadow["2"].dark};`,
    "}",
    "",
  ].join("\n");
}

const COPIES = [
  [
    join(brand, "assets", "logo", "logo-primary-dark.svg"),
    join(frontend, "src", "assets", "brand", "logo-primary-dark.svg"),
  ],
  [join(brand, "assets", "favicon", "favicon.svg"), join(frontend, "public", "favicon.svg")],
  [join(brand, "assets", "favicon", "favicon.ico"), join(frontend, "public", "favicon.ico")],
];

const OUTPUTS = [
  [join(frontend, "src", "styles", "generated", "tokens.css"), tokensCss],
  [join(frontend, "src", "styles", "generated", "theme.css"), Buffer.from(themeCss())],
  [join(frontend, "src", "styles", "generated", "shelfsync-tokens.css"), Buffer.from(layerCss())],
  ...COPIES.map(([from, to]) => [to, readFileSync(from)]),
];

const check = process.argv.includes("--check");
let stale = 0;
for (const [path, content] of OUTPUTS) {
  const name = relative(frontend, path).replaceAll("\\", "/");
  if (check) {
    if (!existsSync(path) || !readFileSync(path).equals(content)) {
      console.error(`out of step with brand/: ${name} (run: npm run tokens)`);
      stale += 1;
    }
    continue;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log(`wrote ${name}`);
}
if (check) {
  if (stale) process.exit(1);
  console.log(`tokens and brand files in step (${OUTPUTS.length} files)`);
}
